'use strict';

var core = require('@tauri-apps/api/core');

function getPassword(service, user) {
    return core.invoke("plugin:keyring|get_password", {
        service,
        user,
    });
}
function setPassword(service, user, password) {
    return core.invoke("plugin:keyring|set_password", {
        service,
        user,
        password,
    });
}
function deletePassword(service, user) {
    return core.invoke("plugin:keyring|delete_password", {
        service,
        user,
    });
}
function getSecret(service, user) {
    return core.invoke("plugin:keyring|get_secret", {
        service,
        user,
    }).then((result) => (result ? new Uint8Array(result) : null));
}
function setSecret(service, user, secret) {
    return core.invoke("plugin:keyring|set_secret", {
        service,
        user,
        secret,
    });
}
function deleteSecret(service, user) {
    return core.invoke("plugin:keyring|delete_secret", {
        service,
        user,
    });
}

exports.deletePassword = deletePassword;
exports.deleteSecret = deleteSecret;
exports.getPassword = getPassword;
exports.getSecret = getSecret;
exports.setPassword = setPassword;
exports.setSecret = setSecret;
